package id.melawai.pegawai;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.location.*;import org.json.*;import java.net.*;import java.io.*;
public class TrackingService extends Service implements LocationListener {
 HandlerThread thread;Handler worker;LocationManager manager;Location latest;String token="";boolean running=false;
 public void onCreate(){super.onCreate();thread=new HandlerThread("MelawaiLocation");thread.start();worker=new Handler(thread.getLooper());manager=(LocationManager)getSystemService(LOCATION_SERVICE);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("tracking","Lokasi selama bertugas",NotificationManager.IMPORTANCE_LOW));}
 void notice(String text){Intent open=new Intent(this,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(this,"tracking").setSmallIcon(id.melawai.pegawai.R.drawable.ic_location).setContentTitle("Melawai · Lokasi selama bertugas").setContentText(text).setContentIntent(pi).setOngoing(true).build();if(Build.VERSION.SDK_INT>=29)startForeground(44,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(44,n);}
 public int onStartCommand(Intent intent,int flags,int id){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return START_NOT_STICKY;}String saved=TokenStore.read(this);if(saved.isEmpty()){stopSelf();return START_NOT_STICKY;}token=saved;notice("Memeriksa sesi kerja dan menunggu GPS");if(!running){running=true;try{manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,30000,10,this,thread.getLooper());if(manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER))manager.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,30000,10,this,thread.getLooper());}catch(Exception e){notice("GPS belum tersedia. Periksa pengaturan lokasi.");}worker.post(tick);}return START_STICKY;}
 JSONObject api(String endpoint,JSONObject body)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(AppConfig.BASE+"/api/mobile/"+endpoint+".php").openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Authorization","Bearer "+token);try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}int status=c.getResponseCode();if(status==401||status==403){TokenStore.clear(this);stopSelf();throw new IOException("Sesi akun berakhir");}if(status!=200)throw new IOException("Server belum menerima lokasi");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 Runnable tick=new Runnable(){public void run(){if(!running)return;try{JSONObject status=api("status",null);if(!status.optBoolean("ok"))throw new IOException();if(!status.optBoolean("active")){stopSelf();return;}if(latest!=null && SystemClock.elapsedRealtimeNanos()-latest.getElapsedRealtimeNanos()<120000000000L){JSONObject body=new JSONObject().put("lat",latest.getLatitude()).put("lng",latest.getLongitude()).put("acc",latest.getAccuracy());JSONObject result=api("point",body);notice(result.optBoolean("ok")?"Lokasi terkirim · "+new java.text.SimpleDateFormat("HH:mm:ss",java.util.Locale.US).format(new java.util.Date()):"Lokasi belum diterima server");}else notice("Menunggu lokasi baru. Pastikan GPS aktif.");}catch(Exception e){if(running)notice("Pembaruan terputus. Periksa internet dan sesi akun.");}if(running)worker.postDelayed(this,30000);}};
 public void onLocationChanged(Location location){latest=location;}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}
 public IBinder onBind(Intent intent){return null;}
 public void onDestroy(){running=false;if(worker!=null)worker.removeCallbacksAndMessages(null);if(manager!=null)manager.removeUpdates(this);if(thread!=null)thread.quitSafely();stopForeground(true);super.onDestroy();}
}
